import itertools
def comp(b): return {'G':'C','C':'G','A':'U','U':'A'}[b]
def rc(s): return ''.join(comp(x) for x in reversed(s))
# Find 4 GC 4-mers such that no two are reverse complements of each other (and none self-RC), 
# so cross-unit antiparallel pairing is impossible.
allgc=[''.join(p) for p in itertools.product('GC',repeat=4)]
# remove self-RC
cand=[s for s in allgc if s!=rc(s)]
# greedily pick 4 pairwise non-RC
chosen=[]
for s in cand:
    if all(rc(s) not in [rc(c) for c in chosen]+chosen and s not in [rc(c) for c in chosen] for _ in [0]):
        # ensure neither s nor rc(s) conflicts
        ok=True
        for c in chosen:
            if s==c or s==rc(c): ok=False;break
        if ok:
            chosen.append(s)
    if len(chosen)>=4: break
print("stems:",chosen)
# outers 3-mers GC, pairwise non-RC, non-self-RC
allgc3=[''.join(p) for p in itertools.product('GC',repeat=3)]
cand3=[s for s in allgc3 if s!=rc(s)]
ch3=[]
for s in cand3:
    ok=True
    for c in ch3:
        if s==c or s==rc(c): ok=False;break
    if ok: ch3.append(s)
    if len(ch3)>=4: break
print("outers:",ch3)
# verify no cross
for a in range(4):
    for b in range(4):
        if a!=b and chosen[a]==rc(chosen[b]): print("STEM spurious",a,b)
        if a!=b and ch3[a]==rc(ch3[b]): print("OUTER spurious",a,b)
